//! Reflected CRC-64 with the ECMA-182 polynomial, initial value zero.
//!
//! The parameters are not the catalogue's CRC-64/XZ: the Python reference
//! (`tauhaulity.core.telemetry.crc64`) initialises the register to zero and
//! applies neither a pre nor a post inversion, because the value is combined
//! with a parity byte into a 64 bit trailer. This module must reproduce that
//! exact variant, otherwise a frame stamped by the Rust backend would fail
//! verification in the Python reader.
//!
//! The 256 entry table is generated by a `const fn` at compile time, so the
//! lookup costs nothing at load and the table cannot drift from the polynomial.

/// Reflected form of the ECMA-182 polynomial x^64 + x^62 + x^57 + x^55 + x^54 +
/// x^53 + x^52 + x^47 + x^46 + x^45 + x^43 + x^42 + x^39 + x^38 + x^37 + x^35 +
/// x^34 + x^33 + x^32 + x^29 + x^27 + x^26 + x^23 + x^22 + x^18 + x^13 + x^12 +
/// x^10 + x^9 + x^7 + x^4 + x + 1.
pub const POLYNOMIAL: u64 = 0x42F0_E1EB_A9EA_3693;

/// Build the 256 entry lookup table for the reflected algorithm.
const fn build_table() -> [u64; 256] {
    let mut table = [0u64; 256];
    let mut index = 0usize;
    while index < 256 {
        let mut value = index as u64;
        let mut bit = 0;
        while bit < 8 {
            value = if value & 1 == 1 {
                (value >> 1) ^ POLYNOMIAL
            } else {
                value >> 1
            };
            bit += 1;
        }
        table[index] = value;
        index += 1;
    }
    table
}

/// 256 entry CRC table generated at compile time.
static TABLE: [u64; 256] = build_table();

/// Return the reflected CRC-64 of a byte slice.
pub fn checksum(data: &[u8]) -> u64 {
    let mut value = 0u64;
    for byte in data {
        let index = ((value ^ u64::from(*byte)) & 0xFF) as usize;
        value = TABLE[index] ^ (value >> 8);
    }
    value
}

#[cfg(test)]
mod tests {
    use super::{checksum, POLYNOMIAL};

    #[test]
    fn empty_input_and_zero_buffer_are_zero() {
        assert_eq!(checksum(b""), 0);
        assert_eq!(checksum(&[0u8; 1000]), 0);
    }

    #[test]
    fn python_reference_vectors_match() {
        // Golden values produced by tauhaulity.core.telemetry.crc64; the Rust
        // backend is only acceptable while it reproduces them byte for byte.
        assert_eq!(checksum(b"a"), 0x6e77_a179_cb48_b4d6);
        assert_eq!(checksum(b"abc"), 0x4e58_5630_adb2_b002);
        assert_eq!(checksum(b"123456789"), 0x4db9_a9f8_7ec1_0c59);
        assert_eq!(
            checksum(b"The quick brown fox jumps over the lazy dog"),
            0x7801_c8eb_84ec_729c
        );
        assert_eq!(checksum(&(0u8..=255).collect::<Vec<u8>>()), 0x2389_d28a_d35e_eed9);
        assert_eq!(checksum(b"hello world"), 0x296d_f20e_6a99_84c1);
        assert_eq!(checksum(&vec![b'a'; 1_000_000]), 0x1fc6_0f36_336c_8798);
    }

    #[test]
    fn table_matches_bitwise_definition() {
        // Recomputing the table with the polynomial definition proves the const
        // generator and the bitwise reference agree for every entry.
        let mut table = [0u64; 256];
        for index in 0..256usize {
            let mut value = index as u64;
            for _ in 0..8 {
                value = if value & 1 == 1 {
                    (value >> 1) ^ POLYNOMIAL
                } else {
                    value >> 1
                };
            }
            table[index] = value;
        }
        for payload in [b"".as_slice(), b"abc", b"123456789"] {
            let mut expected = 0u64;
            for byte in payload {
                expected = table[((expected ^ u64::from(*byte)) & 0xFF) as usize] ^ (expected >> 8);
            }
            assert_eq!(checksum(payload), expected);
        }
    }

    #[test]
    fn single_bit_errors_change_the_checksum() {
        let baseline = checksum(&[0x5Au8; 64]);
        for bit in 0..512usize {
            let mut mutated = [0x5Au8; 64];
            mutated[bit / 8] ^= 1 << (bit % 8);
            assert_ne!(checksum(&mutated), baseline, "bit {bit} did not change the CRC");
        }
    }

    #[test]
    fn crc_is_order_sensitive() {
        assert_ne!(checksum(b"ab"), checksum(b"ba"));
        assert_ne!(checksum(&[0x00, 0x01]), checksum(&[0x01, 0x00]));
    }
}
